import{_ as e,o as t,c as n,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"估算","description":"核心问题：如何准确估算开发工期？故事点和理想人天有什么区别？","frontmatter":{},"headers":[],"relativePath":"engineering/08-project-management/chapter-03-estimation.md","filePath":"engineering/08-project-management/chapter-03-estimation.md"}'),s={name:"engineering/08-project-management/chapter-03-estimation.md"};function l(r,a,p,d,c,h){return t(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="估算" tabindex="-1" data-src-line="1" data-src-file="engineering/08-project-management/chapter-03-estimation.md">估算 <a class="header-anchor" href="#估算" aria-label="Permalink to &quot;估算&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><p data-src-line="3" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><strong>核心问题</strong>：如何准确估算开发工期？故事点和理想人天有什么区别？</p></blockquote><h2 id="_1-估算方法" tabindex="-1" data-src-line="5" data-src-file="engineering/08-project-management/chapter-03-estimation.md">1. 估算方法 <a class="header-anchor" href="#_1-估算方法" aria-label="Permalink to &quot;1. 估算方法&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><tr data-src-line="7" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><th style="text-align:left;">方法</th><th style="text-align:left;">说明</th><th style="text-align:left;">适用场景</th></tr></thead><tbody data-src-line="9" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><tr data-src-line="9" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">故事点</td><td style="text-align:left;">相对估算，不直接对应时间</td><td style="text-align:left;">Sprint 规划</td></tr><tr data-src-line="10" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">理想人天</td><td style="text-align:left;">假设没有打扰的工作天数</td><td style="text-align:left;">项目规划</td></tr><tr data-src-line="11" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">Planning Poker</td><td style="text-align:left;">团队投票达成共识</td><td style="text-align:left;">需求评审</td></tr><tr data-src-line="12" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">T-Shirt Size</td><td style="text-align:left;">S/M/L/XL 粗略估算</td><td style="text-align:left;">早期评估</td></tr></tbody></table><p data-src-line="14" data-src-file="engineering/08-project-management/chapter-03-estimation.md">估算方法解决的是不同层次的问题，选择取决于项目阶段与不确定性。</p><ul data-src-line="16" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><li data-src-line="16" data-src-file="engineering/08-project-management/chapter-03-estimation.md">早期需求信息不足时，用 T-Shirt Size 等粗粒度估算，避免过早制造精度。</li><li data-src-line="17" data-src-file="engineering/08-project-management/chapter-03-estimation.md">团队已有稳定的估算尺度和历史数据时，结合故事点与 Velocity 预测迭代交付能力。</li><li data-src-line="18" data-src-file="engineering/08-project-management/chapter-03-estimation.md">面向明确的项目工期、成本或外部承诺时，理想人天不能直接等同于日历工期，需要说明估算对象、工作范围、风险假设与不确定性。</li><li data-src-line="19" data-src-file="engineering/08-project-management/chapter-03-estimation.md">高不确定性任务优先识别未知因素，必要时安排 Spike 获取信息，再更新估算。</li></ul><h2 id="_2-planning-poker-实践" tabindex="-1" data-src-line="21" data-src-file="engineering/08-project-management/chapter-03-estimation.md">2. Planning Poker 实践 <a class="header-anchor" href="#_2-planning-poker-实践" aria-label="Permalink to &quot;2. Planning Poker 实践&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Planning Poker 流程</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1. PO 讲解用户故事</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 2. 团队成员提问澄清</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 3. 每人选择一张牌（故事点）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 4. 同时亮牌</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 5. 估算差异大时讨论，重新投票</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 6. 达成共识</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 故事点斐波那契数列：1, 2, 3, 5, 8, 13, 21</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 故事点是团队内部的相对估算尺度，综合考虑工作量、技术复杂度和不确定性，</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 不存在跨团队通用的「故事点—代码行数—功能规模」映射。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 各分值的具体含义通过团队历史故事校准，且应保持同一统计口径，</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 不同估算体系下的 Velocity 不能直接比较。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 某个故事估算到 13 点时，应检查需求边界、未知因素与拆分可能性，</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 而不是机械地按分值决定是否拆分。</span></span></code></pre></div><p data-src-line="41" data-src-file="engineering/08-project-management/chapter-03-estimation.md">估算的前提是需求足够清晰。参与投票前先检查用户故事是否符合可估算性要求，见<a href="./chapter-02-requirements.html">需求分析</a>。</p><h2 id="_3-速率-velocity-计算" tabindex="-1" data-src-line="43" data-src-file="engineering/08-project-management/chapter-03-estimation.md">3. 速率（Velocity）计算 <a class="header-anchor" href="#_3-速率-velocity-计算" aria-label="Permalink to &quot;3. 速率（Velocity）计算&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 速率 = 团队每个 Sprint 完成的故事点数</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 用途：预测未来 Sprint 能完成多少工作</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 示例：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Sprint 1: 完成 18 点</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Sprint 2: 完成 22 点</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Sprint 3: 完成 20 点</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 平均速率: 20 点/Sprint</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 假设总需求 100 点</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 预计需要: 100 / 20 = 5 个 Sprint</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 100 / 20 = 5 是简化预测，不是工期承诺。预测成立需要几个前提。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 只统计按团队完成标准真正完成的工作，不把未完成工作按比例计入速率。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 用多个近期 Sprint 观察波动，并结合团队容量、人员变化和工作类型判断。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 历史速率稳定不代表未来速率稳定，人员、依赖、需求范围变化会降低预测价值。</span></span></code></pre></div><p data-src-line="64" data-src-file="engineering/08-project-management/chapter-03-estimation.md">速率如何用于 Sprint 容量评估，见<a href="./chapter-01-agile.html">敏捷开发</a>中的 Sprint Planning 实践。</p><h2 id="_4-估算偏差分析" tabindex="-1" data-src-line="66" data-src-file="engineering/08-project-management/chapter-03-estimation.md">4. 估算偏差分析 <a class="header-anchor" href="#_4-估算偏差分析" aria-label="Permalink to &quot;4. 估算偏差分析&quot;">​</a></h2><table tabindex="0"><thead data-src-line="68" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><tr data-src-line="68" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><th style="text-align:left;">偏差原因</th><th style="text-align:left;">解决方案</th></tr></thead><tbody data-src-line="70" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><tr data-src-line="70" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">需求理解不充分</td><td style="text-align:left;">评审时多提问，明确验收标准</td></tr><tr data-src-line="71" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">技术方案不确定</td><td style="text-align:left;">预研/Spike，先验证再估算</td></tr><tr data-src-line="72" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">遗漏边界条件</td><td style="text-align:left;">使用 Checklist 检查</td></tr><tr data-src-line="73" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">依赖外部团队</td><td style="text-align:left;">将依赖风险纳入估算</td></tr><tr data-src-line="74" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><td style="text-align:left;">过于乐观</td><td style="text-align:left;">参考历史数据，使用三点估算法</td></tr></tbody></table><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 三点估算法（PERT）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// PERT 加权估算值 = (乐观 + 4 × 最可能 + 悲观) / 6</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 示例：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 乐观: 2 天</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 最可能: 3 天</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 悲观: 8 天</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// PERT 加权估算值 = (2 + 4×3 + 8) / 6 = 3.33 天</span></span></code></pre></div><blockquote data-src-line="86" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><p data-src-line="86" data-src-file="engineering/08-project-management/chapter-03-estimation.md"><strong>估算的核心</strong>：估算不是承诺，而是预测。估算的目的是帮助团队做计划，而不是考核个人。允许偏差存在，重要的是持续改进估算的准确性。</p></blockquote>`,16)])])}const o=e(s,[["render",l]]);export{m as __pageData,o as default};
